pub const DOCUMENTS: &[&str] = &["combat", "gameoptions", "civbuilder", "civpowers", "aipersonalities"];

/// The rules' data (the C++ EERules derives from it)
#[repr(C)]
pub struct EERulesData {
    pub mCombat: EECombatRules,
    pub mGameOptions: EEGameOptionRules,
    pub mCivBuilder: EECivBuilderRules,
    pub mCivPowers: EECivPowerRules,
    pub mAIPersonalities: EEAIPersonalityRules,
    pub mEpochs: RuleListC<EEEpochMedia>,
    pub mEpochMusicFromText: bool,
}

pub fn mirror_top(r: &crate::rules::Rules, s: &mut MirrorStore) -> EERulesData {
    EERulesData {
        mCombat: r.combat.mirror(s),
        mGameOptions: r.game_options.mirror(s),
        mCivBuilder: r.civ_builder.mirror(s),
        mCivPowers: r.civ_powers.mirror(s),
        mAIPersonalities: r.ai_personalities.mirror(s),
        mEpochs: { let l = r.epochs.iter().map(|x| x.mirror(s)).collect(); s.list(l) },
        mEpochMusicFromText: r.epoch_music_from_text,
    }
}
